export async function createChat(context: UiPluginContext, agent: string, worktree: string, picks: Picks): Promise<Session> {
  const options = {
    ...(picks.effort === null ? {} : { effort: picks.effort }),
    ...(picks.mode === null ? {} : { mode: picks.mode }),
    ...(picks.plan ? { plan: true } : {})
  }
  return (await context.call('quirky.structured/create', {
    agent,
    worktree,
    deferStart: true,
    ...(picks.model === null ? {} : { model: picks.model }),
    ...(Object.keys(options).length === 0 ? {} : { options })
  })) as Session
}

function load(): void {
    const attempt = ++latest.current
    if (!loadedOnce.current) setPhase({ status: 'loading' })
    context
      .call('quirky.structured/messages', { session: session.id })
      .then((loaded) => {
        if (cancelled.current || attempt !== latest.current) return
        loadedOnce.current = true
        setPhase({ status: 'ready' })
        add(loaded as StructuredMessage[])
      })
      .catch((error: { code?: unknown }) => {
        if (cancelled.current || attempt !== latest.current) return
        if (error?.code === RpcErrorCode.MethodNotFound) {
          loadedOnce.current = false
          setPhase({ status: 'off' })
        } else if (!loadedOnce.current) {
          setPhase({ status: 'failed', message: messageOf(error) })
        }
      })
  }

